const {
  ShopifyHttpError,
  ShopifyGraphQLError,
  normalizeClientError
} = require('./errors');

async function fetchRequest(url, method, headers = {}, body = null) {
  try {
    const response = await fetch(url, {
      method,
      headers: {
        ...headers
      },
      body: body instanceof Buffer ? body : body ? JSON.stringify(body) : null
    });

    if (!response.ok) {
      throw new ShopifyHttpError(`HTTP error! status: ${response.status}`, {
        status: response.status,
        statusText: response.statusText,
        url
      });
    }

    const contentType = response.headers.get('content-type');
    if (contentType && contentType.includes('application/json')) {
      return await response.json();
    }

    return response;
  } catch (error) {
    throw normalizeClientError(error, 'Shopify request failed', {
      details: { url, method }
    });
  }
}

async function graphqlRequest(url, query, variables, headers) {
  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        ...headers
      },
      body: JSON.stringify({
        query,
        variables
      })
    });

    if (!response.ok) {
      throw new ShopifyHttpError(`GraphQL error! status: ${response.status}`, {
        status: response.status,
        statusText: response.statusText,
        url
      });
    }

    const result = await response.json();

    if (result.errors) {
      throw new ShopifyGraphQLError('GraphQL errors returned by Shopify', {
        errors: result.errors,
        url,
        details: {
          query,
          variables
        }
      });
    }

    return result.data;
  } catch (error) {
    throw normalizeClientError(error, 'Shopify GraphQL request failed', {
      details: { url }
    });
  }
}

module.exports = {
  fetchRequest,
  graphqlRequest
};
